import {SIZE,START,GOAL,DIRECTIONS,LEVELS,createLevel,copyBoard,rotate,trace,nextHint,validateProgress} from './core.mjs';
const $=id=>document.getElementById(id),KEY='ce-lumen-trail-progress-v1';
let level=0,board,solution,initial,moves=0,hints=0,history=[],solved=false,progress=LEVELS.map(()=>null),storageOK=true;
const tiles=[],levelButtons=[],point=['50 0','100 50','50 100','0 50'];
function say(text){$('message').textContent=text;}
function storageNote(){document.querySelector('footer span:last-child').lastChild.textContent=storageOK?' · Progress saved in this browser.':' · Progress is temporary in this browser.';}
try{const stored=localStorage.getItem(KEY);if(stored)progress=validateProgress(JSON.parse(stored));}catch{storageOK=false;}
function saveProgress(){try{localStorage.setItem(KEY,JSON.stringify(progress));storageOK=true;}catch{storageOK=false;}storageNote();}
function remember(){const previous=progress[level];progress[level]={complete:true,best:hints===0?Math.min(previous?.best??Infinity,moves):previous?.best??null};saveProgress();}
function renderLevels(){levelButtons.forEach((b,i)=>{b.classList.toggle('done',Boolean(progress[i]));b.setAttribute('aria-pressed',String(i===level));b.setAttribute('aria-label','Trail '+(i+1)+': '+LEVELS[i].name+(progress[i]?', completed':''));});}
function glyph(index){const tile=board[index];let shape='<path class="pipe" d="M'+point[tile.ports[0]]+' L50 50 L'+point[tile.ports[1]]+'"/><circle class="joint" cx="50" cy="50" r="4"/>';if(index===START)shape+='<circle class="endpoint" cx="50" cy="50" r="10"/><circle cx="50" cy="50" r="3" fill="#f7ce80"/>';if(index===GOAL)shape+='<path class="endpoint" d="m50 33 17 17-17 17-17-17Z"/>';return'<svg viewBox="0 0 100 100" aria-hidden="true">'+shape+'</svg>';}
function render(actionMessage){const result=trace(board),justSolved=result.solved&&!solved;solved=result.solved;if(justSolved)remember();const lit=new Set(result.lit);tiles.forEach((b,i)=>{b.classList.toggle('lit',lit.has(i));b.classList.toggle('fixed',board[i].locked);b.classList.toggle('goal',i===GOAL);b.innerHTML=glyph(i);b.setAttribute('aria-disabled',String(board[i].locked||solved));b.setAttribute('aria-label','Row '+(Math.floor(i/SIZE)+1)+', column '+(i%SIZE+1)+': '+(i===START?'fixed source, ':i===GOAL?'fixed home, ':'rotate tile, ')+board[i].ports.map(p=>DIRECTIONS[p]).join(' and ')+(lit.has(i)?', glowing':', unlit'));});
 $('moves').textContent=moves;$('litCount').textContent=result.lit.length;$('undo').disabled=!history.length;$('hint').disabled=solved;$('next').disabled=!solved;$('next').textContent=solved?(level===LEVELS.length-1?'Explore the trails again':'On to the next trail'):'Find the light to continue';$('gameState').textContent=solved?'The light is home':'Finding a connection';$('game').classList.toggle('is-solved',solved);const record=progress[level];$('best').textContent=record?.best!=null?'Best without hints: '+record.best+' turns':record?'Completed with a little help. Try it without hints.':'No rush. There is no timer here.';renderLevels();
 if(justSolved)say((level===LEVELS.length-1?'The last light is home. Beautifully done!':'The light is home!')+' '+moves+' turns'+(hints?' · '+hints+' hint'+(hints===1?'':'s'):' · no hints')+'.'+(!storageOK?' Progress could not be saved in this browser.':''));else if(actionMessage)say(actionMessage);
}
function pushHistory(){history.push({board:copyBoard(board),moves,hints});}
function turn(index){if(board[index].locked||solved)return;pushHistory();board[index].ports=rotate(board[index].ports);moves++;render('The light reaches '+trace(board).lit.length+' tiles. Keep following the glow.');}
function focusTile(index){tiles.forEach(b=>b.tabIndex=-1);tiles[index].tabIndex=0;tiles[index].focus();}
for(let i=0;i<SIZE*SIZE;i++){const b=document.createElement('button');b.className='tile';b.tabIndex=i===0?0:-1;b.addEventListener('click',()=>{tiles.forEach(t=>t.tabIndex=-1);b.tabIndex=0;turn(i);});b.addEventListener('keydown',e=>{let target=null;if(e.key==='ArrowLeft')target=Math.floor(i/SIZE)*SIZE+(i%SIZE+SIZE-1)%SIZE;if(e.key==='ArrowRight')target=Math.floor(i/SIZE)*SIZE+(i%SIZE+1)%SIZE;if(e.key==='ArrowUp')target=(i+SIZE*SIZE-SIZE)%(SIZE*SIZE);if(e.key==='ArrowDown')target=(i+SIZE)%(SIZE*SIZE);if(target!==null){e.preventDefault();focusTile(target);}});tiles.push(b);$('board').append(b);}
LEVELS.forEach((l,i)=>{const b=document.createElement('button');b.textContent=String(i+1).padStart(2,'0');b.addEventListener('click',()=>loadLevel(i));levelButtons.push(b);$('levels').append(b);});
function loadLevel(index){level=index;const data=createLevel(level);board=data.board;solution=data.solution;initial=copyBoard(board);moves=0;hints=0;history=[];solved=false;$('levelCaption').textContent='Trail '+String(level+1).padStart(2,'0')+' / 06';$('levelName').textContent=LEVELS[level].name;$('levelNote').textContent=LEVELS[level].note;render('Turn any tile to rotate it clockwise. The source and home stay fixed.');}
$('undo').addEventListener('click',()=>{const previous=history.pop();if(!previous)return;({board,moves,hints}=previous);render('Last turn undone. A different direction, perhaps?');});
$('hint').addEventListener('click',()=>{if(solved)return;const index=nextHint(board,level);if(index===null)return;pushHistory();board[index].ports=[...solution[index].ports];moves++;hints++;render('A little help: row '+(Math.floor(index/SIZE)+1)+', column '+(index%SIZE+1)+' now points along the trail.');tiles[index].classList.remove('hinted');requestAnimationFrame(()=>tiles[index].classList.add('hinted'));focusTile(index);});
$('restart').addEventListener('click',()=>{board=copyBoard(initial);moves=0;hints=0;history=[];solved=false;render('A fresh start on the same trail. Take your time.');});
$('next').addEventListener('click',()=>{if(!solved)return;loadLevel((level+1)%LEVELS.length);focusTile(0);});
loadLevel(0);storageNote();if(!storageOK)say('Your browser could not read saved progress. You can still play all six trails.');
